; codesweep -- test 1 of the Archimedes sound measurements: the VIDC DAC code sweep.
;
; An Absolute (&FF8) for RISC OS 3. It takes over the sound system the way QTM does:
; Sound_Configure is given a channel handler block whose fill routine writes raw bytes
; into the DMA buffer. It runs 1 channel at 48 us, stereo centre, plays the sequence in
; codesweep_seq.asm (generated by tools/audio/codesweep.py), then puts the sound system
; back as it found it. Escape aborts and restores.
;
; Run it from the command line (F12, or outside the desktop), not under a task that may
; be switched away: the fill routine and its state live in the RMA, but the program waits
; in the foreground.
;
; Build: tools/audio/build_arc.py
;
; Fill routine interface, as QTM's a3_DMAsound uses it:
;   R9 = channel handler block, R10 = buffer end, R11 = byte gap (= channels),
;   R12 = buffer start. Called from the sound interrupt; returns to R14.

	.equ	OS_WriteC,		0x00
	.equ	OS_WriteS,		0x01
	.equ	OS_NewLine,		0x03
	.equ	OS_Exit,		0x11
	.equ	OS_GetEnv,		0x10
	.equ	XOS_Byte,		0x20006
	.equ	XOS_Module,		0x2001E
	.equ	XOS_ReadEscapeState,	0x2002C
	.equ	XOS_ConvertCardinal4,	0x200D8
	.equ	XSound_Configure,	0x60140
	.equ	XSound_Enable,		0x60141
	.equ	XSound_Stereo,		0x60142

; channel handler block and fill state, at the start of the RMA copy
	.equ	BLK_FILL,	0
	.equ	BLK_OVERRUN,	4
	.equ	BLK_LINLOG,	8
	.equ	BLK_LOGSCALE,	12
	.equ	ST_REGS,	16		; R0-R6 of the fill loop, in order:
	;	+16 next record  +20 samples left  +24 phase  +28 current code
	;	+32 code A       +36 code B        +40 half period
	.equ	ST_DONE,	44
	.equ	ST_INDEX,	48		; segments started

	.org	0x8000

start:
	SWI	OS_GetEnv			; R1 = top of application space
	MOV	R13,R1				; RISC OS gives an Absolute no stack
	SWI	OS_WriteS
	.ascii	"VIDC code sweep (test 1): 1 channel, "
	.byte	0
	.p2align 2
	MOV	R0,#SEQ_PERIOD_US
	BL	print_number
	SWI	OS_WriteS
	.ascii	" us, stereo centre. Escape aborts."
	.byte	13,10,0
	.p2align 2

	; claim RMA and copy the handler, its state and the sequence into it
	MOV	R0,#6
	LDR	R3,blob_len
	SWI	XOS_Module
	BVS	fail
	MOV	R10,R2
	ADR	R0,blob_start
	LDR	R1,blob_len
copy:	LDR	R3,[R0],#4
	STR	R3,[R2],#4
	SUBS	R1,R1,#4
	BGT	copy

	ADD	R0,R10,#fill - blob_start
	STR	R0,[R10,#BLK_FILL]
	ADD	R0,R10,#overrun - blob_start
	STR	R0,[R10,#BLK_OVERRUN]
	LDR	R0,seq_offset
	ADD	R0,R10,R0
	STR	R0,[R10,#ST_REGS]

	; read and keep the current configuration, and the OS conversion tables
	MOV	R0,#0
	MOV	R1,#0
	MOV	R2,#0
	MOV	R3,#0
	MOV	R4,#0
	SWI	XSound_Configure
	BVS	fail_free
	ADR	R5,old_config
	STMIA	R5,{R0-R4}
	LDR	R0,[R3,#8]
	STR	R0,[R10,#BLK_LINLOG]
	LDR	R0,[R3,#12]
	STR	R0,[R10,#BLK_LOGSCALE]

	MOV	R0,#0
	SWI	XSound_Enable
	STR	R0,old_enable
	MOV	R0,#2
	SWI	XSound_Enable

	ADR	R5,old_stereo
	MOV	R0,#1
read_st:
	MVN	R1,#127				; -128 = read only
	SWI	XSound_Stereo
	STR	R1,[R5],#4
	ADD	R0,R0,#1
	CMP	R0,#8
	BLE	read_st

	; take over: 1 channel, our period, our handler
	MOV	R0,#1
	MOV	R1,#0
	MOV	R2,#SEQ_PERIOD_US
	MOV	R3,R10
	MOV	R4,#0
	SWI	XSound_Configure
	MOV	R0,#1
set_st:	MOV	R1,#0				; centre
	SWI	XSound_Stereo
	ADD	R0,R0,#1
	CMP	R0,#8
	BLE	set_st

	; wait for the end, showing progress
	MVN	R9,#0
wait:	SWI	XOS_ReadEscapeState
	BCS	aborted
	LDR	R0,[R10,#ST_DONE]
	CMP	R0,#0
	BNE	finished
	LDR	R0,[R10,#ST_INDEX]
	CMP	R0,R9
	BEQ	wait
	MOV	R9,R0
	SWI	OS_WriteS
	.byte	13
	.ascii	"segment "
	.byte	0
	.p2align 2
	BL	print_number
	SWI	OS_WriteS
	.ascii	" of "
	.byte	0
	.p2align 2
	LDR	R0,n_segments
	BL	print_number
	B	wait

aborted:
	MOV	R0,#124				; clear the escape condition
	SWI	XOS_Byte
	BL	restore
	SWI	OS_WriteS
	.byte	13,10
	.ascii	"Aborted; sound system restored."
	.byte	13,10,0
	.p2align 2
	SWI	OS_Exit

finished:
	BL	restore
	SWI	OS_WriteS
	.byte	13,10
	.ascii	"Done; sound system restored."
	.byte	13,10,0
	.p2align 2
	SWI	OS_Exit

restore:
	STMFD	R13!,{R14}
	ADR	R5,old_config
	LDMIA	R5,{R0-R4}
	MOV	R0,#1				; as QTM: buffer, period and handler with 1 channel...
	MOV	R4,#0
	SWI	XSound_Configure
	LDR	R0,old_config			; ...then the channel count
	MOV	R1,#0
	MOV	R2,#0
	MOV	R3,#0
	MOV	R4,#0
	SWI	XSound_Configure
	ADR	R5,old_stereo
	MOV	R0,#1
rest_st:
	LDR	R1,[R5],#4
	SWI	XSound_Stereo
	ADD	R0,R0,#1
	CMP	R0,#8
	BLE	rest_st
	LDR	R0,old_enable
	SWI	XSound_Enable
	MOV	R0,#7
	MOV	R2,R10
	SWI	XOS_Module
	LDMFD	R13!,{PC}

fail_free:
	MOV	R0,#7
	MOV	R2,R10
	SWI	XOS_Module
fail:	SWI	OS_WriteS
	.ascii	"Could not set up the sound system."
	.byte	13,10,0
	.p2align 2
	SWI	OS_Exit

print_number:					; R0 = number
	STMFD	R13!,{R0-R2,R14}
	ADR	R1,numbuf
	MOV	R2,#16
	SWI	XOS_ConvertCardinal4
	SWI	0x02				; OS_Write0
	LDMFD	R13!,{R0-R2,PC}

blob_len:	.long	blob_end - blob_start
seq_offset:	.long	seq_table - blob_start
n_segments:	.long	SEQ_SEGMENTS
old_enable:	.long	0
old_config:	.skip	20
old_stereo:	.skip	32
numbuf:		.skip	16

; ------------------------------------------------------------------ copied to the RMA

	.p2align 2
blob_start:
	.skip	64				; handler block and fill state, zeroed

fill:
	STMFD	R13!,{R0-R8,R14}
	ADD	R8,R9,#ST_REGS
	LDMIA	R8,{R0-R6}
loop:	CMP	R12,R10
	BHS	out
	SUBS	R1,R1,#1
	BMI	next_seg
emit:	STRB	R3,[R12],R11
	SUBS	R2,R2,#1
	BNE	loop
	TEQ	R3,R4				; switch between A and B
	MOVEQ	R3,R5
	MOVNE	R3,R4
	MOV	R2,R6
	B	loop

next_seg:
	LDR	R1,[R0],#4			; samples in this segment, 0 = end
	CMP	R1,#0
	BEQ	seq_end
	LDRB	R4,[R0],#1
	LDRB	R5,[R0],#1
	LDRB	R6,[R0],#1
	LDRB	R7,[R0],#1
	ORR	R6,R6,R7,LSL #8
	MOV	R3,R4
	MOV	R2,R6
	LDR	R7,[R9,#ST_INDEX]
	ADD	R7,R7,#1
	STR	R7,[R9,#ST_INDEX]
	SUB	R1,R1,#1
	B	emit

seq_end:					; silence from here on
	SUB	R0,R0,#4
	MVN	R1,#0x80000000
	MOV	R3,#0
	MOV	R4,#0
	MOV	R5,#0
	MOV	R6,#0x10000
	MOV	R2,R6
	MOV	R7,#1
	STR	R7,[R9,#ST_DONE]
	B	emit

out:	STMIA	R8,{R0-R6}
	LDMFD	R13!,{R0-R8,PC}

overrun:
	MOV	PC,R14

	.p2align 2
	.include "codesweep_seq.asm"
	.p2align 2
blob_end:
